  vec=axmu[l]*rad;_,_,j=gaussian_edit(l,vec,np.float32(1-rad**2/H),jac=True)
  s=np.sqrt(H)/((hr[l]+hr[l+1])/2)
  n=n i[l] if False else ni[l]
