  s1.append(([round(float(q1),2) for q1 in lg1@w1],round(float(np.linalg.norm(w1)),2),round(cos(w1,Gcore[24]),2)))
 print('layer',ls1, 'lex raw', (lg1@Gcore[ls1]).round(2).tolist(), 'gaintriples',s1)"}

