   a02=((u2.astype(np.float64)*(2./(1<<24))-1.)*(np.float32(1./math.sqrt(a2.shape[1])))).astype(np.float32)
   Ainit2[l2,k2]=a02; dA2[l2,k2]=a2-a02
 return Ainit2,dA2
